import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";

const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const playwrightVersion = require("playwright/package.json").version;
const SOURCE = fileURLToPath(import.meta.url);
const ASSETS = path.dirname(SOURCE);
const SUB = path.dirname(path.dirname(ASSETS));
const OUTPUT = path.join(ASSETS, "phase4-browser-qa.json");

const TARGETS = [
  { id: "proposal-zh", path: "report/proposal.html", lang: "zh-CN", kind: "report" },
  { id: "proposal-en", path: "report/proposal.en.html", lang: "en", kind: "report" },
  { id: "visual-zh", path: "visual/index.html", lang: "zh-CN", kind: "visual" },
  { id: "visual-en", path: "visual/index.en.html", lang: "en", kind: "visual" },
];

const VIEWPORTS = [
  { id: "mobile-390x844", width: 390, height: 844 },
  { id: "tablet-768x1024", width: 768, height: 1024 },
  { id: "desktop-1440x900", width: 1440, height: 900 },
  { id: "zoom-200-equivalent", width: 720, height: 450, note: "1440x900 CSS-pixel equivalent at 200% browser zoom" },
];

function localReferenceFailures(references) {
  return references
    .filter((value) => value.startsWith("file:"))
    .map((value) => new URL(value))
    .filter((url) => !fs.existsSync(fileURLToPath(url)))
    .map((url) => url.href);
}

function portableReference(value) {
  if (!value.startsWith("file:")) return value;
  const absolute = fileURLToPath(new URL(value));
  const relative = path.relative(SUB, absolute).replaceAll("\\", "/");
  return relative.startsWith("../") ? `local-file:${path.basename(absolute)}` : `submission:${relative}`;
}

async function inspect(browser, target, viewport) {
  const context = await browser.newContext({
    viewport: { width: viewport.width, height: viewport.height },
    reducedMotion: "reduce",
    colorScheme: "light",
  });
  const page = await context.newPage();
  const consoleErrors = [];
  const pageErrors = [];
  const failedRequests = [];
  const remoteRequests = [];
  page.on("console", (message) => {
    if (message.type() === "error") consoleErrors.push(message.text());
  });
  page.on("pageerror", (error) => pageErrors.push(String(error)));
  page.on("requestfailed", (request) => failedRequests.push(`${request.method()} ${request.url()} ${request.failure()?.errorText ?? "failed"}`));
  page.on("request", (request) => {
    if (/^https?:/i.test(request.url())) remoteRequests.push(request.url());
  });
  const source = path.join(SUB, target.path);
  await page.goto(pathToFileURL(source).href, { waitUntil: "load", timeout: 120_000 });
  await page.evaluate(() => document.fonts.ready);

  const dom = await page.evaluate(() => {
    const visible = (element) => {
      const style = getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      return style.display !== "none" && style.visibility !== "hidden" && rect.width > 0 && rect.height > 0;
    };
    const textSizes = [...document.querySelectorAll("body *")]
      .filter((element) => visible(element) && element.children.length === 0 && element.textContent.trim())
      .map((element) => Number.parseFloat(getComputedStyle(element).fontSize))
      .filter(Number.isFinite);
    const hrefs = [...document.querySelectorAll("a[href]")].map((anchor) => anchor.href);
    const badAnchors = [...document.querySelectorAll('a[href^="#"]')]
      .map((anchor) => anchor.getAttribute("href"))
      .filter((href) => href !== "#" && !document.getElementById(decodeURIComponent(href.slice(1))));
    const tables = [...document.querySelectorAll(".proposal-table")];
    return {
      lang: document.documentElement.lang,
      title: document.title,
      h1_count: document.querySelectorAll("h1").length,
      images: document.images.length,
      broken_images: [...document.images].filter((image) => image.hasAttribute("src") && (!image.complete || image.naturalWidth === 0)).map((image) => image.currentSrc || image.src),
      root_overflow_px: Math.max(0, document.documentElement.scrollWidth - document.documentElement.clientWidth),
      overflow_offenders: [...document.querySelectorAll("body *")]
        .map((element) => ({
          tag: element.tagName,
          class_name: element.className || "",
          right_px: Number(element.getBoundingClientRect().right.toFixed(2)),
          scroll_width_px: element.scrollWidth,
          client_width_px: element.clientWidth,
        }))
        .filter((item) => item.right_px > document.documentElement.clientWidth + 1)
        .sort((a, b) => a.right_px - b.right_px)
        .slice(0, 20),
      bad_anchors: badAnchors,
      hrefs,
      remote_dom_references: [...document.querySelectorAll("[src],[href]")]
        .map((element) => element.src || element.href)
        .filter((value) => /^https?:/i.test(value)),
      reduced_motion: matchMedia("(prefers-reduced-motion: reduce)").matches,
      scroll_behavior: getComputedStyle(document.documentElement).scrollBehavior,
      min_visible_font_px: textSizes.length ? Math.min(...textSizes) : null,
      tables: tables.length,
      focusable_tables: tables.filter((table) => table.tabIndex === 0 && table.getAttribute("role") === "region" && table.hasAttribute("aria-label")).length,
      raw_png_links: [...document.querySelectorAll('a[href$=".png"]')].length,
      zoom_triggers: document.querySelectorAll("[data-zoom-src]").length,
      figure_details: document.querySelectorAll("details.figure-details").length,
    };
  });

  await page.keyboard.press("Home");
  await page.keyboard.press("Tab");
  const firstFocus = await page.evaluate(() => ({ tag: document.activeElement?.tagName, className: document.activeElement?.className, href: document.activeElement?.getAttribute?.("href") }));
  let skipTarget = null;
  if (firstFocus.href?.startsWith("#")) {
    await page.keyboard.press("Enter");
    skipTarget = await page.evaluate(() => `${document.activeElement?.tagName ?? ""}#${document.activeElement?.id ?? ""}`);
  }

  const tabSequence = [];
  for (let index = 0; index < 18; index += 1) {
    await page.keyboard.press("Tab");
    tabSequence.push(await page.evaluate(() => {
      const active = document.activeElement;
      return `${active?.tagName ?? ""}${active?.id ? `#${active.id}` : ""}${active?.className && typeof active.className === "string" ? `.${active.className.split(/\s+/)[0]}` : ""}`;
    }));
  }

  let tableKeyboard = null;
  const table = page.locator(".proposal-table").first();
  if (await table.count()) {
    await table.focus();
    const before = await table.evaluate((element) => element.scrollLeft);
    await page.keyboard.press("ArrowRight");
    const after = await table.evaluate((element) => element.scrollLeft);
    tableKeyboard = { focused: await table.evaluate((element) => document.activeElement === element), before, after, scrollable: await table.evaluate((element) => element.scrollWidth > element.clientWidth) };
  }

  let drawer = null;
  const drawerOpen = page.locator("[data-open]");
  if (await drawerOpen.count()) {
    await drawerOpen.click();
    drawer = await page.evaluate(() => {
      const modal = document.querySelector("[data-drawer]");
      return {
        visible: Boolean(modal && !modal.hidden),
        focus_inside: Boolean(modal?.contains(document.activeElement)),
        inert_peers: [...document.body.children].filter((element) => element !== modal && element.inert).length,
      };
    });
    await page.keyboard.press("Tab");
    drawer.tab_inside = await page.evaluate(() => document.querySelector("[data-drawer]")?.contains(document.activeElement));
    await page.keyboard.press("Escape");
    drawer.closed = await page.evaluate(() => document.querySelector("[data-drawer]")?.hidden === true);
    drawer.returned_focus = await drawerOpen.evaluate((element) => document.activeElement === element);
  }

  let lightbox = null;
  const zoom = page.locator("[data-zoom-src]").first();
  if (await zoom.count()) {
    await zoom.click();
    lightbox = await page.evaluate(() => {
      const dialog = document.querySelector("[data-lightbox]");
      return {
        open: Boolean(dialog?.open),
        focus_inside: Boolean(dialog?.contains(document.activeElement)),
        image_alt: dialog?.querySelector("img")?.alt ?? "",
      };
    });
    for (let index = 0; index < 7; index += 1) await page.keyboard.press("Tab");
    lightbox.tab_trapped = await page.evaluate(() => document.querySelector("[data-lightbox]")?.contains(document.activeElement));
    await page.locator('[data-lightbox-zoom="200"]').click();
    lightbox.zoom_200_pan = await page.evaluate(() => {
      const viewport = document.querySelector(".lightbox-viewport");
      const image = viewport?.querySelector("img");
      return {
        image_css_width: image ? getComputedStyle(image).width : null,
        viewport_client_width: viewport?.clientWidth ?? null,
        viewport_scroll_width: viewport?.scrollWidth ?? null,
        pannable: Boolean(viewport && viewport.scrollWidth > viewport.clientWidth),
      };
    });
    await page.keyboard.press("Escape");
    lightbox.closed = await page.evaluate(() => document.querySelector("[data-lightbox]")?.open === false);
    lightbox.returned_focus = await zoom.evaluate((element) => document.activeElement === element);
  }

  let figureDetails = null;
  const details = page.locator("details.figure-details").first();
  if (await details.count()) {
    const summary = details.locator("summary");
    await summary.focus();
    await page.keyboard.press("Enter");
    figureDetails = await details.evaluate((element) => {
      const viewport = element.querySelector(".figure-details-viewport");
      return {
        open: element.open,
        focus_on_summary: document.activeElement === element.querySelector("summary"),
        pannable_200: Boolean(viewport && viewport.scrollWidth > viewport.clientWidth),
        semantic_summary: element.querySelectorAll(".figure-details-panel p").length >= 2,
      };
    });
    const detailsViewport = details.locator(".figure-details-viewport");
    await detailsViewport.focus();
    figureDetails.viewport_focus_ring = await detailsViewport.evaluate((element) => {
      const style = getComputedStyle(element);
      return {
        focused: document.activeElement === element,
        width_px: Number.parseFloat(style.outlineWidth),
        style: style.outlineStyle,
        color: style.outlineColor,
        offset_px: Number.parseFloat(style.outlineOffset),
      };
    });
    await summary.focus();
    await page.keyboard.press("Enter");
    figureDetails.closed = await details.evaluate((element) => element.open === false);
    figureDetails.returned_focus = await summary.evaluate((element) => document.activeElement === element);
  }

  const missingLocalReferences = localReferenceFailures(dom.hrefs);
  dom.hrefs = dom.hrefs.map(portableReference);
  const result = {
    target: target.id,
    kind: target.kind,
    viewport,
    dom,
    local_reference_failures: missingLocalReferences,
    requests: { remote: remoteRequests, failed: failedRequests },
    errors: { console: consoleErrors, page: pageErrors },
    keyboard: { first_focus: firstFocus, skip_target: skipTarget, tab_sequence: tabSequence, table: tableKeyboard, drawer, lightbox, figure_details: figureDetails },
  };
  await context.close();
  return result;
}

function failures(results) {
  const items = [];
  for (const result of results) {
    const id = `${result.target}/${result.viewport.id}`;
    const dom = result.dom;
    if (dom.lang !== TARGETS.find((target) => target.id === result.target).lang) items.push(`${id}: lang=${dom.lang}`);
    if (dom.h1_count !== 1) items.push(`${id}: h1_count=${dom.h1_count}`);
    if (dom.broken_images.length) items.push(`${id}: broken images`);
    if (dom.root_overflow_px > 1) items.push(`${id}: root overflow ${dom.root_overflow_px}px`);
    if (dom.bad_anchors.length) items.push(`${id}: bad anchors ${dom.bad_anchors.join(",")}`);
    if (dom.remote_dom_references.length || result.requests.remote.length) items.push(`${id}: remote resources`);
    if (result.local_reference_failures.length) items.push(`${id}: missing local references`);
    if (result.requests.failed.length || result.errors.console.length || result.errors.page.length) items.push(`${id}: browser errors`);
    if (!dom.reduced_motion || dom.scroll_behavior === "smooth") items.push(`${id}: reduced motion not honored`);
    if (result.keyboard.skip_target !== "MAIN#content") items.push(`${id}: skip target ${result.keyboard.skip_target}`);
    if (dom.raw_png_links !== 0) items.push(`${id}: raw PNG links=${dom.raw_png_links}`);
    if (result.kind === "visual" && dom.zoom_triggers !== 11) items.push(`${id}: zoom triggers=${dom.zoom_triggers}`);
    if (result.kind === "report" && (dom.zoom_triggers !== 0 || dom.figure_details !== 11)) items.push(`${id}: report details/zoom=${dom.figure_details}/${dom.zoom_triggers}`);
    if (result.kind === "report" && (dom.tables !== 7 || dom.focusable_tables !== 7)) items.push(`${id}: table focus ${dom.focusable_tables}/${dom.tables}`);
    if (result.keyboard.drawer && (!result.keyboard.drawer.focus_inside || !result.keyboard.drawer.tab_inside || !result.keyboard.drawer.closed || !result.keyboard.drawer.returned_focus || result.keyboard.drawer.inert_peers < 1)) items.push(`${id}: drawer focus/inert failure`);
    const lightbox = result.keyboard.lightbox;
    if (result.kind === "visual" && (!lightbox?.open || !lightbox.focus_inside || !lightbox.tab_trapped || !lightbox.closed || !lightbox.returned_focus || !lightbox.zoom_200_pan?.pannable || !lightbox.image_alt)) items.push(`${id}: lightbox focus/zoom failure`);
    const details = result.keyboard.figure_details;
    if (result.kind === "report" && (!details?.open || !details.focus_on_summary || !details.pannable_200 || !details.semantic_summary || !details.closed || !details.returned_focus)) items.push(`${id}: native details focus/zoom failure`);
    if (result.kind === "report" && (!details?.viewport_focus_ring?.focused || details.viewport_focus_ring.width_px < 4 || details.viewport_focus_ring.style === "none")) items.push(`${id}: details viewport focus ring ${JSON.stringify(details?.viewport_focus_ring)}`);
  }
  return items;
}

const browser = await chromium.launch({ headless: true });
const browserVersion = await browser.version();
const results = [];
try {
  for (const target of TARGETS) {
    for (const viewport of VIEWPORTS) results.push(await inspect(browser, target, viewport));
  }
} finally {
  await browser.close();
}
const failed = failures(results);
const payload = {
  schema_version: "jingzhang-phase4-browser-qa-v1",
  generated_at: "2026-08-28",
  toolchain: { node: process.version, playwright: playwrightVersion, chromium: browserVersion, command: "node visual/assets/phase4-browser-audit.mjs" },
  targets: TARGETS,
  viewports: VIEWPORTS,
  summary: { checks: results.length, failures: failed.length, ok: failed.length === 0 },
  failures: failed,
  results,
};
fs.writeFileSync(OUTPUT, `${JSON.stringify(payload, null, 2)}\n`, "utf8");
console.log(JSON.stringify(payload.summary, null, 2));
if (failed.length) {
  console.error(failed.join("\n"));
  process.exitCode = 1;
}

#!/usr/bin/env python3
"""Machine-check Phase 4 PDF structure, typography, text, and 200-DPI rendering.

This is an evidence audit, not a PDF/UA conformance claim.  The available
toolchain does not include PAC or veraPDF, so the script records that boundary
and checks the concrete properties that are locally inspectable.
"""

from __future__ import annotations

import argparse
import base64
import io
import json
import math
import platform
import re
import shutil
import subprocess
import tempfile
from collections import Counter
from pathlib import Path
from typing import Any

import PIL
import brotli
import fontTools
import pypdf
import pymupdf as fitz
from fontTools.ttLib import TTFont
from PIL import Image, ImageChops, ImageStat
from pypdf import PdfReader


HERE = Path(__file__).resolve().parent
SUBMISSION = HERE.parents[1]
DRAWINGS = SUBMISSION / "drawings"
REPORT = HERE / "phase4-pdf-qa.json"
GENERATION = HERE / "phase4-generation-contract.json"
FONT_CSS = HERE / "font-subset.css"
EXPECTED_FONTTOOLS_VERSION = "4.63.0"
EXPECTED_BROTLI_VERSION = "1.2.0"
EXPECTED_WOFF2_HEAD_TIMESTAMP = 2082840000
EXPECTED_ENGLISH_OUTLINE_COUNTS = {
    "a3-booklet.en.pdf": 30,
    "a0-boards.en.pdf": 22,
}
FORBIDDEN_ENGLISH_OUTLINE_GLUE = (
    "ZeroOverlaps",
    "ThreeDetailed",
    "OneGrammar",
    "HumanTakeover",
    "Thermal-SafetyBench",
    "MatchingClinic",
    "TrialRoom",
    "+Components",
)

PDFS = (
    ("a3_zh", DRAWINGS / "a3-booklet.pdf", 12, "A3", "zh-CN", 8.0, 12),
    ("a3_en", DRAWINGS / "a3-booklet.en.pdf", 12, "A3", "en", 8.0, 12),
    ("a0_zh", DRAWINGS / "a0-boards.pdf", 2, "A0", "zh-CN", 14.0, 7),
    ("a0_en", DRAWINGS / "a0-boards.en.pdf", 2, "A0", "en", 14.0, 7),
)

EXPECTED_POINTS = {
    "A3": (1190.55, 841.89),
    "A0": (3370.39, 2383.94),
}


def run_text(command: list[str]) -> str:
    result = subprocess.run(command, check=True, capture_output=True)
    payload = result.stdout + result.stderr
    return payload.decode("utf-8", errors="replace")


def flatten_outline(items: list[Any]) -> list[str]:
    flattened: list[str] = []
    for item in items:
        if isinstance(item, list):
            flattened.extend(flatten_outline(item))
        else:
            flattened.append(str(getattr(item, "title", item)))
    return flattened


def canonical_outline_title(value: str) -> str:
    return re.sub(r"\s+", " ", value).strip()


def audit_final_css_woff2(expected_timestamp: int, generation: dict[str, Any]) -> tuple[dict[str, Any], list[str]]:
    failures: list[str] = []
    css = FONT_CSS.read_text(encoding="utf-8")
    payloads = re.findall(r"base64,([^)]*)\) format\('woff2'\)", css)
    fonts: list[dict[str, Any]] = []
    if len(payloads) != 2:
        failures.append(f"font-subset.css contains {len(payloads)} WOFF2 payloads, expected 2")
    for weight, payload in zip((400, 700), payloads):
        raw = base64.b64decode(payload, validate=True)
        font = TTFont(io.BytesIO(raw), recalcTimestamp=False)
        created = int(font["head"].created)
        modified = int(font["head"].modified)
        fonts.append({
            "weight": weight,
            "woff2_bytes": len(raw),
            "head.created": created,
            "head.modified": modified,
        })
        if (created, modified) != (expected_timestamp, expected_timestamp):
            failures.append(
                f"final CSS WOFF2 weight {weight} raw head timestamps "
                f"{created}/{modified}, expected {expected_timestamp}/{expected_timestamp}"
            )
    toolchain = {"fontTools": fontTools.__version__, "Brotli": brotli.__version__}
    if toolchain != {"fontTools": EXPECTED_FONTTOOLS_VERSION, "Brotli": EXPECTED_BROTLI_VERSION}:
        failures.append(f"font toolchain drift: {toolchain}")
    contract = generation.get("font_subset_contract", {})
    if contract.get("raw_head_created_modified") != EXPECTED_WOFF2_HEAD_TIMESTAMP:
        failures.append("generation contract WOFF2 head timestamp is not 2082840000")
    if contract.get("fontTools") != EXPECTED_FONTTOOLS_VERSION or contract.get("Brotli") != EXPECTED_BROTLI_VERSION:
        failures.append("generation contract fontTools/Brotli versions drift")
    if "fixed at 2082840000" not in css or "fixed at 0" in css:
        failures.append("font-subset.css timestamp declaration does not match the final WOFF2 bytes")
    return ({
        "source": FONT_CSS.relative_to(SUBMISSION).as_posix(),
        "decoded_payloads": len(payloads),
        "expected_timestamp": expected_timestamp,
        "toolchain": toolchain,
        "fonts": fonts,
        "ok": not failures,
    }, failures)


def structure_counts(reader: PdfReader) -> Counter[str]:
    counts: Counter[str] = Counter()
    seen: set[int] = set()

    def walk(value: Any) -> None:
        try:
            value = value.get_object()
        except AttributeError:
            pass
        identity = id(value)
        if identity in seen:
            return
        seen.add(identity)
        if isinstance(value, dict):
            if value.get("/S"):
                counts[str(value["/S"])] += 1
            if value.get("/Alt"):
                counts["Alt"] += 1
            if "/K" in value:
                walk(value["/K"])
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(reader.trailer["/Root"]["/StructTreeRoot"])
    return counts


def effective_font_sizes(page: Any) -> list[float]:
    sizes: list[float] = []

    def visitor(text: str, cm: list[float], tm: list[float], font: Any, size: float) -> None:
        del tm, font
        if text.strip():
            x_scale = math.hypot(float(cm[0]), float(cm[1]))
            sizes.append(float(size) * x_scale)

    page.extract_text(visitor_text=visitor)
    return sizes


def native_protocol_evidence(path: Path, format_name: str) -> dict[str, Any]:
    """Measure the actual selectable F08/F11 text layer with a second parser."""
    document = fitz.open(path)
    page_indices = (8, 11) if format_name == "A3" else (1,)
    lower_y, upper_y = ((112.0, 810.0) if format_name == "A3" else (390.0, 1385.0))
    target = 9.0 if format_name == "A3" else 18.0
    pages: list[dict[str, Any]] = []
    try:
        for page_index in page_indices:
            page = document[page_index]
            spans: list[dict[str, Any]] = []
            for block in page.get_text("dict").get("blocks", []):
                for line in block.get("lines", []):
                    for span in line.get("spans", []):
                        text = str(span.get("text", "")).strip()
                        bbox = span.get("bbox", (0, 0, 0, 0))
                        if text and float(bbox[1]) >= lower_y and float(bbox[3]) <= upper_y:
                            spans.append({"text": text, "size_pt": round(float(span["size"]), 3), "bbox_pt": [round(float(value), 2) for value in bbox]})
            minimum = min((span["size_pt"] for span in spans), default=0.0)
            pages.append(
                {
                    "page": page_index + 1,
                    "region_y_pt": [lower_y, upper_y],
                    "selectable_spans": len(spans),
                    "minimum_pt": minimum,
                    "target_pt": target,
                    "met": bool(spans) and minimum + 0.01 >= target,
                }
            )
    finally:
        document.close()
    return {"parser": f"PyMuPDF {fitz.VersionBind}", "pages": pages, "met": all(page["met"] for page in pages)}


def english_a3_header_separator_evidence(path: Path) -> dict[str, Any]:
    document = fitz.open(path)
    pages: list[dict[str, Any]] = []
    try:
        for page_index in range(1, len(document)):
            page = document[page_index]
            separators = []
            for drawing in page.get_drawings():
                rect = drawing.get("rect")
                if rect and 100 <= rect.y0 <= 150 and rect.width >= page.rect.width * 0.8 and rect.height <= 3:
                    separators.append(rect)
            if len(separators) != 1:
                pages.append({"page": page_index + 1, "separator_count": len(separators), "intersections": 1, "failure": "expected exactly one running-header separator"})
                continue
            separator = separators[0]
            spans = []
            intersections = 0
            for block in page.get_text("dict").get("blocks", []):
                for line in block.get("lines", []):
                    for span in line.get("spans", []):
                        bbox = fitz.Rect(span.get("bbox", (0, 0, 0, 0)))
                        if float(span.get("size", 0)) < 12 or bbox.y0 >= separator.y1:
                            continue
                        intersects = bbox.intersects(separator)
                        intersections += int(intersects)
                        spans.append({
                            "text": str(span.get("text", "")).strip(),
                            "role": "title" if bbox.x0 < page.rect.width * 0.65 else "judgment",
                            "bbox_pt": [round(value, 2) for value in bbox],
                            "gap_to_separator_pt": round(separator.y0 - bbox.y1, 2),
                            "intersects_separator": intersects,
                        })
            pages.append({
                "page": page_index + 1,
                "figure": f"F{page_index:02d}",
                "separator_bbox_pt": [round(value, 2) for value in separator],
                "text_spans": spans,
                "minimum_gap_pt": min((span["gap_to_separator_pt"] for span in spans), default=None),
                "intersections": intersections,
            })
    finally:
        document.close()
    return {
        "parser": f"PyMuPDF {fitz.VersionBind}",
        "required_pages": 11,
        "required_intersections": 0,
        "pages": pages,
        "total_intersections": sum(page["intersections"] for page in pages),
        "ok": len(pages) == 11 and all(page["intersections"] == 0 for page in pages),
    }


def font_table(path: Path) -> tuple[list[dict[str, Any]], list[str]]:
    output = run_text(["pdffonts", str(path)])
    lines = [line.rstrip() for line in output.splitlines()]
    rows: list[dict[str, Any]] = []
    failures: list[str] = []
    for line in lines[2:]:
        if not line.strip():
            continue
        columns = line.split()
        if len(columns) < 8:
            continue
        row = {
            "name": columns[0],
            "type": " ".join(columns[1:-6]),
            "encoding": columns[-6],
            "embedded": columns[-5],
            "subset": columns[-4],
            "unicode": columns[-3],
        }
        rows.append(row)
        if "NotoSansSC" not in row["name"]:
            failures.append(f"unexpected font {row['name']}")
        if (row["embedded"], row["subset"], row["unicode"]) != ("yes", "yes", "yes"):
            failures.append(f"font flags not yes/yes/yes for {row['name']}")
    if not rows:
        failures.append("pdffonts returned no font rows")
    return rows, failures


def render_poppler(path: Path, output_dir: Path, expected_pages: int) -> dict[str, Any]:
    stem = output_dir / path.stem
    subprocess.run(
        ["pdftoppm", "-png", "-r", "200", str(path), str(stem)],
        check=True,
        capture_output=True,
    )
    images = sorted(output_dir.glob(f"{path.stem}-*.png"))
    page_results: list[dict[str, Any]] = []
    for index, image_path in enumerate(images, start=1):
        with Image.open(image_path) as image:
            rgb = image.convert("RGB")
            white = Image.new("RGB", rgb.size, "white")
            bbox = ImageChops.difference(rgb, white).getbbox()
            stats = ImageStat.Stat(rgb.resize((max(1, rgb.width // 20), max(1, rgb.height // 20))))
            variance = sum(stats.var) / len(stats.var)
            page_results.append(
                {
                    "page": index,
                    "pixels": [rgb.width, rgb.height],
                    "nonwhite_bbox": list(bbox) if bbox else None,
                    "mean_channel_variance": round(variance, 3),
                    "nonblank": bbox is not None and variance > 1.0,
                }
            )
    return {
        "renderer": run_text(["pdftoppm", "-v"]).splitlines()[0] if shutil.which("pdftoppm") else None,
        "dpi": 200,
        "images": len(images),
        "expected_images": expected_pages,
        "pages": page_results,
        "ok": len(images) == expected_pages and all(page["nonblank"] for page in page_results),
    }


def audit_pdf(
    key: str,
    path: Path,
    expected_pages: int,
    format_name: str,
    expected_lang: str,
    target_min_pt: float,
    expected_figures: int,
    render_dir: Path,
    generation: dict[str, Any],
    negative_outline_glue: bool,
) -> tuple[dict[str, Any], list[str]]:
    failures: list[str] = []
    reader = PdfReader(path)
    root = reader.trailer["/Root"]
    pages = len(reader.pages)
    if pages != expected_pages:
        failures.append(f"page count {pages}, expected {expected_pages}")

    media_sizes = []
    per_page_text = []
    per_page_font_min = []
    all_text = []
    for number, page in enumerate(reader.pages, start=1):
        box = page.mediabox
        width, height = float(box.width), float(box.height)
        media_sizes.append([round(width, 2), round(height, 2)])
        extracted = page.extract_text() or ""
        all_text.append(extracted)
        per_page_text.append({"page": number, "characters": len(extracted), "nonempty": bool(extracted.strip())})
        sizes = effective_font_sizes(page)
        minimum = min(sizes) if sizes else 0.0
        per_page_font_min.append({"page": number, "minimum_pt": round(minimum, 3)})
        expected_width, expected_height = EXPECTED_POINTS[format_name]
        if abs(width - expected_width) > 2.0 or abs(height - expected_height) > 2.0:
            failures.append(f"page {number} media box {width:.2f}x{height:.2f} is not {format_name}")
        if not extracted.strip():
            failures.append(f"page {number} has no selectable text")
        if minimum + 0.01 < target_min_pt:
            failures.append(f"page {number} minimum {minimum:.3f}pt below {target_min_pt:.1f}pt target")

    text = "\n".join(all_text)
    required_terms = ["Jing-Zhang In Situ", "Human Takeover", "SC10 + IM06"]
    if format_name == "A0":
        required_terms.extend(["13", "12/12"])
    term_presence = {term: term.casefold() in text.casefold() for term in required_terms}
    for term, present in term_presence.items():
        if not present:
            failures.append(f"selectable text missing {term!r}")

    direct_visibility: dict[str, Any] = {}
    if format_name == "A3":
        f08_text = all_text[8]
        f11_text = all_text[11]
        scenario_presence = {f"SC{index:02d}": f"SC{index:02d}" in f08_text for index in range(1, 13)}
        disposition_terms = ("fail_stop", "fail_pause", "unknown_stop")
        disposition_presence = {term: term in f11_text for term in disposition_terms}
        prohibited_terms = (
            ("默认人脸识别", "情绪识别", "社会评分", "预测性执法", "未披露敏感推断")
            if expected_lang == "zh-CN"
            else ("facial recognition", "emotion recognition", "social scoring", "predictive policing", "undisclosed sensitive inference")
        )
        prohibited_presence = {term: term.casefold() in f11_text.casefold() for term in prohibited_terms}
        red_test_presence = {f"RT-{index:02d}": f"RT-{index:02d}" in f11_text for index in range(1, 5)}
        direct_visibility = {
            "f08_scenarios": scenario_presence,
            "f11_red_tests": red_test_presence,
            "f11_dispositions": disposition_presence,
            "f11_prohibited_boundary": prohibited_presence,
            "native_layout_has_no_summary_overlay": True,
            "met": all(scenario_presence.values()) and all(red_test_presence.values()) and len([value for value in disposition_presence.values() if value]) >= 3 and all(prohibited_presence.values()),
        }
        if not direct_visibility["met"]:
            failures.append("F08/F11 direct visibility contract is incomplete")

    marked = bool(root.get("/MarkInfo", {}).get("/Marked"))
    has_structure = "/StructTreeRoot" in root
    language = str(root.get("/Lang", ""))
    title = str(reader.metadata.title or "")
    if not marked or not has_structure:
        failures.append("tag structure absent")
    role_map: dict[str, str] = {}
    if has_structure:
        struct = root["/StructTreeRoot"].get_object()
        role_ref = struct.get("/RoleMap")
        role_object = role_ref.get_object() if role_ref is not None else {}
        role_map = {str(key): str(value) for key, value in role_object.items()}
        if role_map.get("/Strong") != "/Span":
            failures.append(f"StructTreeRoot RoleMap /Strong={role_map.get('/Strong')!r}, expected '/Span'")
    if language != expected_lang:
        failures.append(f"document language {language!r}, expected {expected_lang!r}")
    if not title:
        failures.append("document title absent")
    if not all(str(page.get("/Tabs", "")) == "/S" for page in reader.pages):
        failures.append("one or more pages do not use structure-order tabbing")

    counts = structure_counts(reader)
    if counts["/Figure"] != expected_figures or counts["Alt"] != expected_figures:
        failures.append(
            f"Figure/Alt counts {counts['/Figure']}/{counts['Alt']}, expected {expected_figures}/{expected_figures}"
        )
    if counts["/H1"] < 1 or counts["/Document"] != 1:
        failures.append("document/H1 structure is incomplete")

    outlines = flatten_outline(reader.outline)
    if len(outlines) < expected_pages:
        failures.append(f"only {len(outlines)} flattened bookmarks for {expected_pages} pages")
    outline_assertion: dict[str, Any] | None = None
    required_outline_count = EXPECTED_ENGLISH_OUTLINE_COUNTS.get(path.name)
    if required_outline_count is not None:
        contract = generation.get("pdf_outline_assertions", {}).get(path.name, {})
        expected_titles = contract.get("expected_titles", [])
        audited_titles = list(outlines)
        if negative_outline_glue:
            for index, title in enumerate(audited_titles):
                if "Zero Overlaps" in title:
                    audited_titles[index] = title.replace("Zero Overlaps", "ZeroOverlaps")
                    break
        glued = sorted({token for token in FORBIDDEN_ENGLISH_OUTLINE_GLUE for title in audited_titles if token in title})
        canonical = [canonical_outline_title(title) for title in audited_titles]
        idempotent = [canonical_outline_title(title) for title in canonical] == canonical
        exact = audited_titles == expected_titles
        outline_assertion = {
            "expected_count": required_outline_count,
            "actual_count": len(audited_titles),
            "expected_titles": expected_titles,
            "actual_titles": audited_titles,
            "forbidden_glue": glued,
            "normalization_idempotent": idempotent,
            "exact_titles": exact,
            "ok": len(audited_titles) == required_outline_count and len(expected_titles) == required_outline_count and exact and not glued and canonical == audited_titles and idempotent,
        }
        if not outline_assertion["ok"]:
            failures.append(
                f"English outline contract failed: count={len(audited_titles)}/{required_outline_count}, "
                f"exact={exact}, forbidden_glue={glued}, idempotent={idempotent}"
            )

    fonts, font_failures = font_table(path)
    failures.extend(font_failures)
    rendered = render_poppler(path, render_dir, expected_pages)
    if not rendered["ok"]:
        failures.append("200-DPI Poppler render count or nonblank check failed")

    pdfinfo = run_text(["pdfinfo", str(path)])
    tagged_line = next((line for line in pdfinfo.splitlines() if line.startswith("Tagged:")), "")
    if "yes" not in tagged_line.casefold():
        failures.append("pdfinfo does not report Tagged: yes")

    native_typography = native_protocol_evidence(path, format_name)
    if not native_typography["met"]:
        failures.append("native F08/F11 selectable text is below the Phase 4 layout target")

    return (
        {
            "key": key,
            "path": path.relative_to(SUBMISSION).as_posix(),
            "pages": pages,
            "expected_pages": expected_pages,
            "format": format_name,
            "media_boxes_pt": media_sizes,
            "metadata": {"title": title, "language": language, "marked": marked, "tagged_pdfinfo": tagged_line},
            "structure_counts": dict(counts),
            "role_map": role_map,
            "bookmarks": outlines,
            "outline_assertion": outline_assertion,
            "page_tabs_structure_order": all(str(page.get("/Tabs", "")) == "/S" for page in reader.pages),
            "selectable_text": per_page_text,
            "required_term_presence": term_presence,
            "direct_visibility": direct_visibility,
            "native_protocol_typography": native_typography,
            "font_target": {
                "design_target_pt": target_min_pt,
                "tolerance_pt": 0.01,
                "per_page_minimum_pt": per_page_font_min,
                "met": all(item["minimum_pt"] + 0.01 >= target_min_pt for item in per_page_font_min),
            },
            "fonts": fonts,
            "render_200dpi": rendered,
            "failures": failures,
            "ok": not failures,
        },
        failures,
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--negative-outline-glue", action="store_true", help="read-only negative fixture for a restored glued English title")
    parser.add_argument("--negative-font-timestamp", action="store_true", help="read-only negative fixture with an incorrect raw head expectation")
    cli = parser.parse_args()
    generation = json.loads(GENERATION.read_text(encoding="utf-8"))
    if cli.negative_outline_glue or cli.negative_font_timestamp:
        fixture_failures: list[str] = []
        fixture_report: dict[str, Any] = {"schema": "jz-phase4-pdf-negative-fixture/v1"}
        if cli.negative_outline_glue:
            expected = generation["pdf_outline_assertions"]["a3-booklet.en.pdf"]["expected_titles"]
            actual = flatten_outline(PdfReader(DRAWINGS / "a3-booklet.en.pdf").outline)
            for index, title in enumerate(actual):
                if "Zero Overlaps" in title:
                    actual[index] = title.replace("Zero Overlaps", "ZeroOverlaps")
                    break
            glued = sorted({token for token in FORBIDDEN_ENGLISH_OUTLINE_GLUE for title in actual if token in title})
            if actual != expected:
                fixture_failures.append("restored glued outline title differs from the exact 30-node contract")
            if glued:
                fixture_failures.append(f"forbidden glued outline tokens: {glued}")
            fixture_report["outline"] = {"actual_count": len(actual), "expected_count": 29, "forbidden_glue": glued}
        if cli.negative_font_timestamp:
            font_report, font_failures = audit_final_css_woff2(EXPECTED_WOFF2_HEAD_TIMESTAMP + 1, generation)
            fixture_failures.extend(font_failures)
            fixture_report["font"] = font_report
        fixture_report["failures"] = fixture_failures
        fixture_report["ok"] = not fixture_failures
        print(json.dumps(fixture_report, ensure_ascii=False, indent=2))
        return 0 if fixture_report["ok"] else 1

    tool_versions = {
        "python": platform.python_version(),
        "pypdf": pypdf.__version__,
        "Pillow": PIL.__version__,
        "PyMuPDF": fitz.VersionBind,
        "fontTools": fontTools.__version__,
        "Brotli": brotli.__version__,
    }
    for tool, args in (
        ("pdfinfo", ["pdfinfo", "-v"]),
        ("pdffonts", ["pdffonts", "-v"]),
        ("pdftotext", ["pdftotext", "-v"]),
        ("pdftoppm", ["pdftoppm", "-v"]),
    ):
        tool_versions[tool] = run_text(args).splitlines()[0]

    audits = []
    failures = []
    with tempfile.TemporaryDirectory(prefix="jz-phase4-pdf-") as temporary:
        render_dir = Path(temporary)
        for item in PDFS:
            audit, pdf_failures = audit_pdf(
                *item,
                render_dir,
                generation,
                cli.negative_outline_glue and item[0] == "a3_en",
            )
            audits.append(audit)
            failures.extend(f"{item[0]}: {failure}" for failure in pdf_failures)

    font_timestamp = EXPECTED_WOFF2_HEAD_TIMESTAMP + int(cli.negative_font_timestamp)
    font_assertions, font_failures = audit_final_css_woff2(font_timestamp, generation)
    failures.extend(f"font_subset: {failure}" for failure in font_failures)

    english_header_evidence = english_a3_header_separator_evidence(DRAWINGS / "a3-booklet.en.pdf")
    if not english_header_evidence["ok"]:
        failures.append("drawings/a3-booklet.en.pdf: running-header text intersects the separator")

    report = {
        "schema": "jz-phase4-pdf-qa/v1",
        "scope": "four Phase 4 presentation PDFs",
        "claim_boundary": "Concrete tag, structure, text, typography, font, and rendering evidence only; not a PDF/UA conformance claim.",
        "page_contract": {
            "a3_pages_per_language": 12,
            "a0_pages_per_language": 2,
            "total_pages": sum(item["pages"] for item in audits),
            "expected_total": 28,
        },
        "tools": tool_versions,
        "execution": {
            "command": "uv run --with pymupdf==1.28.2 --with pypdf==6.10.0 --with pillow==12.1.1 --with fonttools==4.63.0 --with brotli==1.2.0 python visual/assets/phase4-pdf-audit.py",
            "poppler_full_render": "pdftoppm -png -r 200 <pdf> <temporary-output-prefix>",
        },
        "conformance_tool_availability": {
            "veraPDF": bool(shutil.which("verapdf")),
            "PAC": False,
            "boundary": "No veraPDF or PAC available; PDF/UA is not asserted.",
        },
        "advisories": [
            "F08/F11 use native selectable text and retain Figure-level grouping rather than semantic Table tags; the structure tree, detailed Alt, same-page text, accessible HTML, and machine matrices remain equivalent entry points.",
            "The accessible HTML report and Visual provide structured textual summaries, keyboard-accessible original-image dialogs, and the authoritative machine-readable matrices as equivalent detailed entry points; PDF/UA is not asserted.",
        ],
        "pdfs": audits,
        "final_woff2_head_assertions": font_assertions,
        "english_a3_header_separator_bbox": english_header_evidence,
        "failures": failures,
        "ok": not failures and sum(item["pages"] for item in audits) == 28,
    }
    if not cli.negative_outline_glue and not cli.negative_font_timestamp:
        REPORT.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(json.dumps({"ok": report["ok"], "pdfs": len(audits), "pages": report["page_contract"]["total_pages"], "failures": len(failures)}, ensure_ascii=False))
    return 0 if report["ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
